//! The Frame-class attributes of every Frame class, through the `Frame`
//! trait, checked against the C library.
//!
//! `frame_class_oracle/cases.rs` is generated by
//! `tools/oracle_fixtures/frame_class_attrs_probe.c`, which builds one object
//! of each class, sets each Frame-class attribute on its own and reads every
//! one back. It pins each class's defaults and how the compound classes
//! share an attribute: a CmpFrame (and a SpecFluxFrame) with its
//! components, and a FrameSet and a Region with the Frame they present,
//! whose "inner" rows record what that Frame reports afterwards.

// Generated; formatted by its generator rather than rustfmt.
#[rustfmt::skip]
#[path = "frame_class_oracle/cases.rs"]
mod cases;

use cases::V;

use ast_core::frames::{
    BasicFrameBuilder, CmpFrame, DSBSpecFrame, DynFrame, FluxFrame, FluxSystem, Frame, FrameSet,
    SkyFrame, SkySystem, SpecFluxFrame, SpecFrame, SpecSystem, TimeFrame, TimeSystem,
};
use ast_core::regions::{CircleBuilder, Region};

fn make(class: &str) -> DynFrame {
    match class {
        "Frame" => Box::new(BasicFrameBuilder::new(2).build().unwrap()),
        "SkyFrame" => Box::new(SkyFrame::new(SkySystem::Icrs)),
        "SpecFrame" => Box::new(SpecFrame::new(SpecSystem::Wavelen)),
        "DSBSpecFrame" => Box::new(DSBSpecFrame::new(SpecSystem::Wavelen)),
        "TimeFrame" => Box::new(TimeFrame::new(TimeSystem::Mjd)),
        "FluxFrame" => Box::new(FluxFrame::new(FluxSystem::FluxDen)),
        "SpecFluxFrame" => Box::new(SpecFluxFrame::new(
            SpecFrame::new(SpecSystem::Wavelen),
            FluxFrame::new(FluxSystem::FluxDen),
        )),
        "CmpFrame" => Box::new(CmpFrame::new(
            Box::new(SkyFrame::new(SkySystem::Icrs)),
            Box::new(SpecFrame::new(SpecSystem::Wavelen)),
        )),
        "FrameSet" => Box::new(FrameSet::new(Box::new(SkyFrame::new(SkySystem::Icrs)))),
        "Circle" => Box::new(
            CircleBuilder::new(SkyFrame::new(SkySystem::Icrs), vec![0.0, 0.0])
                .unwrap()
                .radius(0.01)
                .build()
                .unwrap(),
        ),
        other => panic!("unexpected class {other}"),
    }
}

/// The Frame whose attributes show the effect of setting one on `f`.
fn inner(class: &str, f: &dyn Frame) -> Option<DynFrame> {
    let any = f.as_any();
    match class {
        "CmpFrame" => Some(any.downcast_ref::<CmpFrame>().unwrap().frame1().snapshot()),
        "SpecFluxFrame" => Some(Box::new(
            any.downcast_ref::<SpecFluxFrame>()
                .unwrap()
                .spec_frame()
                .clone(),
        )),
        "FrameSet" => Some(any.downcast_ref::<FrameSet>().unwrap().current().snapshot()),
        "Circle" => Some(
            any.downcast_ref::<ast_core::regions::Circle>()
                .unwrap()
                .get_region_frame(),
        ),
        _ => None,
    }
}

/// Radians from a decimal angle in degrees, as C reads ObsLat and ObsLon
/// through a SkyAxis (skyaxis.c `AxisUnformat`).
fn c_sky_radians(text: &str) -> f64 {
    const DEG2RAD: f64 = 3600.0 * 4.848_136_811_095_36e-6;
    text.parse::<f64>().unwrap() * DEG2RAD
}

/// An Epoch year as an MJD, by C's 1984 rule.
fn year_to_mjd(year: f64) -> f64 {
    let mut f = BasicFrameBuilder::new(1).build().unwrap();
    f.set_epoch_year(year);
    f.epoch_mjd()
}

/// An MJD as the year C reports.
fn mjd_to_year(mjd: f64) -> f64 {
    let mut f = BasicFrameBuilder::new(1).build().unwrap();
    f.set_epoch_mjd(mjd);
    f.epoch_year()
}

fn apply(f: &mut dyn Frame, setting: &str) {
    let Some((name, value)) = setting.split_once('=') else {
        return;
    };
    let int = || value.parse::<i64>().unwrap();
    let dbl = || value.parse::<f64>().unwrap();
    match name {
        "Title" => f.set_title(value),
        "Domain" => f.set_domain(value),
        "Epoch" => f.set_epoch_mjd(year_to_mjd(dbl())),
        "Digits" => f.set_digits(int() as i32),
        "ObsLat" => f.set_obs_lat(c_sky_radians(value)),
        "ObsLon" => f.set_obs_lon(c_sky_radians(value)),
        "ObsAlt" => f.set_obs_alt(dbl()),
        "Dtai" => f.set_dtai(dbl()),
        "Dut1" => f.set_dut1(dbl()),
        "MinAxes" => f.set_min_axes(int() as usize),
        "MaxAxes" => f.set_max_axes(int() as usize),
        "MatchEnd" => f.set_match_end(int() != 0),
        "PreserveAxes" => f.set_preserve_axes(int() != 0),
        "Permute" => f.set_permute(int() != 0),
        "Ident" => f.set_ident(value),
        other => panic!("unexpected setting {other}"),
    }
    .unwrap();
}

/// C's formatted ObsLat / ObsLon (`N10:00:00.00`) in radians.
fn c_obs_angle(text: &str) -> f64 {
    let (sign, rest) = match text.split_at(1) {
        ("N" | "E", rest) => (1.0, rest),
        ("S" | "W", rest) => (-1.0, rest),
        _ => panic!("unexpected {text}"),
    };
    let mut value = 0.0;
    let mut scale = 1.0;
    for field in rest.split(':') {
        value += field.parse::<f64>().unwrap() * scale;
        scale /= 60.0;
    }
    sign * value.to_radians()
}

fn value(f: &dyn Frame, attr: &str) -> (V, Option<bool>) {
    let s = |v: String| V::S(Box::leak(v.into_boxed_str()));
    match attr {
        "Title" => (s(f.title()), Some(f.test_title())),
        "Domain" => (s(f.domain().to_string()), Some(f.test_domain())),
        "Epoch" => (V::D(mjd_to_year(f.epoch_mjd())), Some(f.test_epoch())),
        "Digits" => (V::I(f.digits()), Some(f.test_digits())),
        "ObsLat" => (V::D(f.obs_lat()), Some(f.test_obs_lat())),
        "ObsLon" => (V::D(f.obs_lon()), Some(f.test_obs_lon())),
        "ObsAlt" => (V::D(f.obs_alt()), Some(f.test_obs_alt())),
        "Dtai" => (V::D(f.dtai()), Some(f.test_dtai())),
        "Dut1" => (V::D(f.dut1()), Some(f.test_dut1())),
        "MinAxes" => (V::I(f.min_axes() as i32), Some(f.test_min_axes())),
        "MaxAxes" => (V::I(f.max_axes() as i32), Some(f.test_max_axes())),
        "MatchEnd" => (V::I(i32::from(f.match_end())), Some(f.test_match_end())),
        "PreserveAxes" => (
            V::I(i32::from(f.preserve_axes())),
            Some(f.test_preserve_axes()),
        ),
        "Permute" => (V::I(i32::from(f.permute())), Some(f.test_permute())),
        "Ident" => (s(f.ident().to_string()), Some(f.test_ident())),
        "ActiveUnit" => (V::I(i32::from(f.get_active_unit())), None),
        other => panic!("unexpected attribute {other}"),
    }
}

#[test]
fn every_class_matches_the_c_library() {
    let mut failures = Vec::new();
    let mut last: Option<(&str, &str)> = None;
    let mut objects: Option<(DynFrame, Option<DynFrame>)> = None;
    for &(class, setting, whose, attr, expected, expected_test) in cases::CASES {
        if last != Some((class, setting)) {
            let mut f = make(class);
            apply(f.as_mut(), setting);
            let i = inner(class, f.as_ref());
            objects = Some((f, i));
            last = Some((class, setting));
        }
        let (f, i) = objects.as_ref().unwrap();
        let target: &dyn Frame = match whose {
            "self" => f.as_ref(),
            _ => i.as_deref().expect("an inner Frame"),
        };
        let (got, got_test) = value(target, attr);
        let matches = match (expected, got) {
            // C formats ObsLat and ObsLon to 0.01 arcsec.
            (V::S(c), V::D(rad)) if attr.starts_with("Obs") => {
                (c_obs_angle(c) - rad).abs() < 0.006 / 206_264.806
            }
            (V::D(e), V::D(g)) if attr == "Epoch" => (e - g).abs() < 1e-9,
            (e, g) => e == g,
        };
        if !matches || (expected_test.is_some() && expected_test != got_test) {
            failures.push(format!(
                "{class} {setting:?} {whose} {attr}: got {got:?} test {got_test:?}, C gives {expected:?} test {expected_test:?}"
            ));
        }
    }
    assert!(
        failures.is_empty(),
        "{} of {} cases differ:\n{}",
        failures.len(),
        cases::CASES.len(),
        failures.join("\n")
    );
}
